import { createServer } from "node:http";

type StatusUpdate = { message: string };
const latest: StatusUpdate[] = [];

export const server = createServer(function handle(request, response) {
    // TODO: limit the body size, parse JSON, and answer with a status code
    const chunks: Buffer[] = [];
    request.on("data", function onChunk(chunk: Buffer) {
        chunks.push(chunk);
    });
    request.on("end", function onEnd() {
        const body = JSON.parse(Buffer.concat(chunks).toString("utf8")) as StatusUpdate;
        latest.push(body);
        response.writeHead(200, { "content-type": "text/plain" });
        response.end("ok");
    });
});
